export const HEVY_CLIENT_OPTION_INDEXES = {
	getWorkouts: 1,
	getWorkout: 1,
	createWorkout: 1,
	updateWorkout: 2,
	getWorkoutCount: 0,
	getWorkoutEvents: 1,
	getRoutines: 1,
